import './style.css';
import './audio.css';
import './captions.css';
const $ = s=>document.querySelector(s);
const esc = s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();
const defaults=()=>({version:1,name:'Untitled story',ratio:'16:9',fit:'contain',resolution:1080,fps:30,quality:'balanced',format:'mp4',clips:[],audioClips:[],captions:[],titles:[],burnCaptions:true,captionSize:.052,captionColor:'#ffffff',captionFont:'Arial',captionPreset:'clean',captionBold:true,captionItalic:false,captionOutline:3,captionShadow:true,captionBox:false,captionUppercase:false,captionPosition:'bottom',canvasBackground:'blur',canvasBlur:24,canvasColor:'#15191b',musicId:null,musicVolume:.25});
let project=defaults(), media=[],selectedAudio=null,audioPlayers=[],selected=null,tab='media',playhead=0,playing=false,undo=[],redo=[],saveTimer,worker,busy=false,aiResult='',status='All changes saved',transcribeStatus='',currentJob=null,jobTimer,zoom=60;
let fonts=['Arial','Arial Black','Calibri','Cambria','Consolas','Georgia','Impact','Segoe UI','Tahoma','Times New Roman','Trebuchet MS','Verdana'];
let ai={preset:'ollama',baseUrl:'http://127.0.0.1:11434/v1',key:'',model:'',speechModel:'whisper-1',models:[],verified:false};
try{ai={...ai,...JSON.parse(localStorage.getItem('framecut-ai')||'{}'),key:'',verified:false}}catch{}
const asset=id=>media.find(m=>m.id===id);
const duration=c=>Math.max(0,(c.end-c.start)/(+c.speed||1));
const total=()=>project.clips.reduce((a,c)=>a+duration(c),0);
const offset=index=>project.clips.slice(0,index).reduce((a,c)=>a+duration(c),0);
const clip=()=>project.clips.find(c=>c.id===selected);
const fmt=s=>`${Math.floor(Math.max(0,s)/60).toString().padStart(2,'0')}:${(Math.max(0,s)%60).toFixed(1).padStart(4,'0')}`;
const clock=s=>{const ms=Math.max(0,Math.round(s*1000));return `${Math.floor(ms/3600000).toString().padStart(2,'0')}:${Math.floor(ms/60000%60).toString().padStart(2,'0')}:${Math.floor(ms/1000%60).toString().padStart(2,'0')},${(ms%1000).toString().padStart(3,'0')}`};
async function api(url,body,method=body?'POST':'GET'){const r=await fetch(url,{method,...(body?{headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});const data=await r.json();if(!r.ok)throw Error(data.error||'Request failed');return data}
function toast(text,error=false){$('.toast')?.remove();const t=document.createElement('div');t.className='toast'+(error?' error':'');t.textContent=text;document.body.append(t);setTimeout(()=>t.remove(),6500)}
function checkpoint(){undo.push(JSON.stringify(project));if(undo.length>60)undo.shift();redo=[]}
function save(){status='Saving…';updateStatus();clearTimeout(saveTimer);saveTimer=setTimeout(async()=>{try{await api('/api/project',project,'PUT');status='All changes saved'}catch{status='Could not save project'}updateStatus()},450)}
function updateStatus(){if($('#save-status'))$('#save-status').textContent=status}
function change(fn,{history=true,full=true}={}){if(history)checkpoint();fn();save();if(full)render();else{renderTimeline();updateOverlay()}}
function download(name,text,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function field(label,control){return `<div class="field"><label>${label}</label>${control}</div>`}
function select(values,value,attrs=''){return `<select ${attrs}>${values.map(v=>{const [id,label]=Array.isArray(v)?v:[v,v];return `<option value="${esc(id)}" ${String(id)===String(value)?'selected':''}>${esc(label)}</option>`}).join('')}</select>`}
function pInput(key,type='number',attrs=''){return `<input type="${type}" data-project="${key}" value="${esc(project[key])}" ${attrs}>`}
function cInput(c,key,attrs=''){return `<input type="number" data-clip="${key}" value="${esc(c[key])}" ${attrs}>`}
function render(){
  const wasPlaying=playing;pause();playing=false;
  $('#app').innerHTML=`<header class="topbar"><div class="brand"><div class="logo">▰</div><div>FrameCut<span>YOUR STORY. SIMPLIFIED.</span></div></div><span style="color:#3c484d">/</span><input aria-label="Project name" class="project-name" id="project-name" value="${esc(project.name)}"><span class="pill">LOCAL WORKSPACE</span><div class="grow"></div><span id="save-status" class="statusbar">${status}</span><button class="quiet" data-action="project-menu">Project ▾</button><button class="primary" data-action="export">Export video ↗</button></header>
  <main class="layout"><nav class="rail">${[['media','▦','Media'],['captions','▤','Captions'],['text','T','Text'],['audio','♫','Audio'],['ai','✧','AI tools']].map(([id,icon,label])=>`<button class="${tab===id?'active':''}" data-tab="${id}"><b>${icon}</b>${label}</button>`).join('')}<div class="grow"></div><button data-action="settings"><b>⚙</b>AI setup</button><button data-action="help"><b>?</b>Help</button></nav>
  <aside class="library" id="library">${library()}</aside>
  <section class="preview"><div class="preview-top"><span class="status-dot"></span> CANVAS PREVIEW <div class="grow"></div>${select(Object.keys(ratios),project.ratio,'id="quick-ratio" aria-label="Canvas aspect ratio"')}<span>Fit</span></div><div class="stage-wrap"><div class="stage" id="stage"><video id="canvas-background" class="canvas-background" muted playsinline></video><video id="video" playsinline></video><div class="stage-empty" id="empty-stage"><div class="big-icon">▱</div><h2>A little footage. A great story.</h2><p>Import a video, then add it to your timeline.</p></div><div class="caption-overlay" id="caption-overlay"></div><div class="title-overlay" id="title-overlay"></div></div></div><div class="controls"><span class="time" id="time">${fmt(playhead)} <span class="muted">/ ${fmt(total())}</span></span><button data-action="previous" title="Previous clip">|◀</button><button class="play" id="play" data-action="play" title="Play / pause (Space)">▶</button><button data-action="next" title="Next clip">▶|</button><div class="grow" style="max-width:30px"></div><span class="muted" style="font-size:10px">${project.resolution}p · ${project.fps} fps</span></div><input id="scrubber" aria-label="Playhead" type="range" min="0" max="${Math.max(.1,total())}" step=".01" value="${playhead}"><audio id="music-preview"></audio></section>
  <aside class="inspector" id="inspector">${inspector()}</aside><section class="timeline"><div class="timeline-toolbar"><button data-action="undo" title="Undo (Ctrl+Z)" ${undo.length?'':'disabled'}>↶</button><button data-action="redo" title="Redo (Ctrl+Y)" ${redo.length?'':'disabled'}>↷</button><span style="color:#3b464a">│</span><button data-action="split" ${clip()||selectedAudio?'':'disabled'}>✂ Split at playhead</button><button data-action="duplicate" ${clip()||selectedAudio?'':'disabled'}>⧉ Duplicate</button><button data-action="delete" ${clip()||selectedAudio?'':'disabled'}>⌫ Remove</button><small>${project.clips.length} clips · ${fmt(total())}</small><button data-action="zoom-out">−</button><button data-action="zoom-in">+</button></div><div class="timeline-scroll" id="timeline-content"></div></section></main><input id="file-input" class="hidden" type="file" multiple accept="video/*,audio/*,.mkv,.mov,.m4v"><input id="subtitle-input" class="hidden" type="file" accept=".srt,.vtt"><input id="project-input" class="hidden" type="file" accept=".json,.framecut">`;
  renderTimeline();bind();setupVideo();if(wasPlaying)play();
}
const ratios={'16:9':'Landscape','9:16':'Vertical','1:1':'Square','4:5':'Portrait','4:3':'Classic','21:9':'Cinema','2:1':'Wide','3:4':'Portrait classic','1.85:1':'Cinema flat','2.35:1':'Cinema scope'};
function library(){
  if(tab==='media')return `<div class="section-head"><h2>Media library</h2><span class="muted">${media.length} files</span></div><div class="dropzone" id="dropzone"><div class="upload-icon">↥</div><strong>Bring your story in</strong><p>Drop video or audio files here<br>MP4, MOV, MKV, MP3, WAV & more</p><button data-action="import" class="primary">+ Import media</button></div><div style="margin-top:18px">${media.map(m=>`<div class="asset">${m.thumbnail?`<img src="${m.thumbnail}" alt="">`:'<div class="thumb">♫</div>'}<div><div class="asset-name" title="${esc(m.name)}">${esc(m.name)}</div><small>${fmt(m.duration)}${m.video?` · ${m.width} × ${m.height}`:' · Audio'}</small></div><button data-add="${m.id}" title="Add to ${m.video?'timeline':'music track'}">+</button></div>`).join('')}</div><div class="welcome-note">Everything stays on this computer.<br>Original media is kept intact.<br><span class="keyboard">Space</span> play · <span class="keyboard">S</span> split · <span class="keyboard">Ctrl Z</span> undo</div>`;
  if(tab==='captions')return `<div class="section-head"><h2>Captions</h2><button data-action="add-caption">+</button></div><div class="panel-card"><h3>Let your words do the talking</h3><p>Generate timed captions for the selected clip. Local AI downloads a model on first use.</p><button class="primary" data-action="transcribe" ${busy?'disabled':''}>✧ ${busy?'Working…':'Auto-caption selected clip'}</button><div class="busy">${esc(transcribeStatus)}</div></div><div class="row" style="margin-bottom:15px"><button data-action="import-subtitles">Import SRT / VTT</button><button data-action="save-subtitles">Save SRT</button></div>${captionStylePanel()}${field('Speech engine',select([['local','Local Whisper · no API key'],['api','API connection']],localStorage.getItem('framecut-speech')||'local','id="speech-engine"'))}${project.captions.map((c,i)=>`<div class="caption-row"><div class="row"><input aria-label="Caption start" data-caption="${i}" data-key="start" type="number" min="0" step=".1" value="${c.start.toFixed(2)}"><span class="muted" style="flex:0">→</span><input aria-label="Caption end" data-caption="${i}" data-key="end" type="number" min="0" step=".1" value="${c.end.toFixed(2)}"><button data-remove-caption="${i}">×</button></div><textarea aria-label="Caption text" data-caption="${i}" data-key="text">${esc(c.text)}</textarea></div>`).join('')||'<p class="helper">No captions yet. Auto-caption your selected clip to get started.</p>'}`;
  if(tab==='text')return `<div class="section-head"><h2>Text overlays</h2></div><div class="panel-card"><h3>Give it a title</h3><p>Add a simple title at the top of your video. Timing uses seconds on your project timeline.</p><button class="primary" data-action="add-title">+ Add text overlay</button></div>${project.titles.map((c,i)=>`<div class="caption-row"><div class="row"><input aria-label="Title start" data-title="${i}" data-key="start" type="number" min="0" step=".1" value="${c.start}"><span style="flex:0">→</span><input aria-label="Title end" data-title="${i}" data-key="end" type="number" min="0" step=".1" value="${c.end}"><button data-remove-title="${i}">×</button></div><textarea aria-label="Title text" data-title="${i}" data-key="text">${esc(c.text)}</textarea></div>`).join('')}`;
  if(tab==='audio')return audioLibrary();
  if(tab==='legacy-audio')return `<div class="section-head"><h2>Audio & music</h2></div><div class="panel-card"><h3>Set the mood</h3><p>Import an audio file and add it as your music bed. It loops to fit your video.</p><button data-action="import" class="primary">+ Import audio</button></div>${field('Background music',select([['','No music'],...media.filter(m=>m.audio&&!m.video).map(m=>[m.id,m.name])],project.musicId||'','data-project="musicId"'))}${field('Music volume',`${pInput('musicVolume','range','min="0" max="2" step=".05"')}<small>${Math.round(project.musicVolume*100)}%</small>`)}<div class="divider"></div><p class="helper">Select a timeline clip to adjust its original audio volume, mute it, or change playback speed.</p>`;
  return `<div class="section-head"><h2>AI tools</h2><button data-action="settings">⚙</button></div><div class="panel-card"><h3>✧ Automatic captions</h3><p>Turn speech into editable subtitles using local Whisper or your API.</p><button data-action="captions-tab">Open captions →</button></div><div class="panel-card"><h3>⌁ Remove silence</h3><p>Split the selected clip into speaking sections. Review the result and undo if needed. Runs locally, no AI model required.</p><button data-action="silence" ${busy?'disabled':''}>Find & remove pauses</button></div><div class="panel-card"><h3>✎ Writing assistant</h3><p>Use your local or API text model with the project captions.</p>${select([['titles','Suggest 5 catchy titles'],['summary','Summarize this video'],['description','Write a video description'],['translate','Translate captions to a language']],'titles','id="ai-task"')}<input id="ai-language" placeholder="Translation language, e.g. Spanish" style="margin:8px 0"><button data-action="ai-write" ${busy?'disabled':''}>${busy?'Working…':'Generate from captions'}</button>${aiResult?`<div class="ai-result">${esc(aiResult)}</div><button data-action="copy-ai">Copy result</button>`:''}</div><p class="helper">AI is optional. Cloud requests send only the selected audio or caption text when you click Generate. Switch provider any time in AI setup.</p>`;
}
function inspector(){if(tab==='audio'&&selectedAudio)return audioInspector();const c=clip(),m=c&&asset(c.mediaId);return `<div class="eyebrow">Make it yours</div><h2>Canvas & clip</h2><div class="field"><label>Aspect ratio</label><div class="presets">${Object.entries(ratios).map(([id,label])=>`<button class="${project.ratio===id?'selected':''}" data-ratio="${id}" title="${label}"><span class="ratio-icon" style="${id==='9:16'?'width:13px;height:22px':id==='1:1'?'width:19px;height:19px':''}"></span>${id}</button>`).join('')}</div></div>${field('Frame your video',select([['contain','Fit · show the whole frame'],['crop','Fill · crop the edges']],project.fit,'data-project="fit"'))}${canvasControls()}<div class="divider"></div>${c?`<h3>${esc(m?.name||'Selected clip')}</h3><p class="helper">Source: ${fmt(m?.duration||0)} · Clip: ${fmt(duration(c))}</p><div class="row">${field('Trim in (sec)',cInput(c,'start',`min="0" max="${c.end-.05}" step=".1"`))}${field('Trim out (sec)',cInput(c,'end',`min="${c.start+.05}" max="${m?.duration}" step=".1"`))}</div>${field('Speed',select([.25,.5,.75,1,1.25,1.5,2,3,4].map(n=>[n,n+'×']),c.speed,'data-clip="speed"'))}${field('Clip volume',`<input aria-label="Clip volume" type="range" data-clip="volume" min="0" max="2" step=".05" value="${c.volume}"><small>${Math.round(c.volume*100)}%${c.volume===0?' · Muted':''}</small>`)}${field('Fade in / out',select([[0,'None'],[.25,'Quick · 0.25 sec'],[.5,'Soft · 0.5 sec'],[1,'Slow · 1 sec']],c.fade,'data-clip="fade"'))}<details><summary class="helper" style="cursor:pointer;margin-bottom:14px">Color adjustments</summary>${['brightness','contrast','saturation'].map(key=>field(key[0].toUpperCase()+key.slice(1),`<input aria-label="${key}" type="range" data-clip="${key}" value="${c[key]}" min="${key==='brightness'?-.5:0}" max="${key==='brightness'?.5:2}" step=".05">`)).join('')}</details><button class="full-width" data-action="detach-audio" style="margin-bottom:12px">♫ Detach audio to its own track</button><div class="row"><button data-action="move-left">← Earlier</button><button data-action="move-right">Later →</button></div>`:'<p class="helper">Select a clip on the timeline to trim, adjust speed, control audio, and change color.</p>'}<div class="divider"></div><h3>Caption style</h3>${field('Text color',pInput('captionColor','color'))}${field('Text size',pInput('captionSize','range','min=".025" max=".1" step=".002"'))}<label class="row" style="justify-content:flex-start"><input type="checkbox" data-project="burnCaptions" ${project.burnCaptions?'checked':''} style="flex:none"> Include captions in export</label>`}
function renderTimeline(){if(!$('#timeline-content'))return;const width=Math.max(550,total()*zoom);$('#timeline-content').innerHTML=`<div class="ruler" style="width:${width}px">${Array.from({length:11},(_,i)=>`<span>${fmt(total()*i/10)}</span>`).join('')}</div><div class="track" style="width:${width}px"><div class="track-label">VIDEO</div>${project.clips.map(c=>`<div class="timeline-clip ${selected===c.id?'selected':''}" style="width:${Math.max(35,duration(c)/Math.max(total(),.1)*width)}px" data-select="${c.id}" title="${esc(asset(c.mediaId)?.name)} · ${fmt(duration(c))}"><strong>${esc(asset(c.mediaId)?.name||'Missing media')}</strong><div class="wave"></div></div>`).join('')||'<div class="empty-track">Your timeline is ready. Add a clip from the media library to begin.</div>'}</div><div class="caption-track" style="width:${width}px"><div class="track-label">CAPTIONS</div>${project.captions.map((c,i)=>`<div class="caption-block" data-seek="${c.start}" style="left:${c.start/Math.max(total(),.1)*width}px;width:${Math.max(24,(c.end-c.start)/Math.max(total(),.1)*width)}px">${esc(c.text)}</div>`).join('')}</div>${audioTracks(width)}${project.musicId?`<div class="music-chip" style="width:${width}px">♫ ${esc(asset(project.musicId)?.name)} · ${Math.round(project.musicVolume*100)}%</div>`:''}`}
function setupVideo(){const background=$('#canvas-background');if(background){background.pause();background.style.display=project.fit!=='crop'&&project.canvasBackground==='blur'?'block':'none';background.style.filter='blur('+(project.canvasBlur*$('#stage').clientHeight/1080)+'px)';}$('#stage').style.background=project.canvasBackground==='color'?project.canvasColor:'#090b0b';audioPlayers.forEach(p=>p.audio.pause());audioPlayers=(project.audioClips||[]).map(c=>{const a=new Audio(asset(c.mediaId)?.url);a.preload='auto';return {id:c.id,audio:a}});const v=$('#video'),c=clip();const stage=$('#stage');stage.style.aspectRatio=project.ratio.replace(':','/');stage.style.width=Number(project.ratio.split(':')[0])<Number(project.ratio.split(':')[1])?'auto':'100%';stage.style.height=Number(project.ratio.split(':')[0])<Number(project.ratio.split(':')[1])?'100%':'auto';if(!c){$('#empty-stage').classList.remove('hidden');return}const m=asset(c.mediaId);if(!m)return;$('#empty-stage').classList.add('hidden');v.src=m.url;if(background){background.src=m.url;background.muted=true;background.playbackRate=+c.speed}v.style.objectFit=project.fit==='crop'?'cover':'contain';v.style.filter=`brightness(${1+c.brightness}) contrast(${c.contrast}) saturate(${c.saturation})`;v.playbackRate=+c.speed;v.volume=Math.min(1,c.volume);v.muted=c.volume===0;const start=offset(project.clips.indexOf(c));const seek=c.start+Math.min(duration(c),Math.max(0,playhead-start))*c.speed;v.addEventListener('loadedmetadata',()=>{v.currentTime=Math.min(c.end-.01,seek);updateOverlay()},{once:true});v.addEventListener('timeupdate',()=>{if(!playing)return;playhead=start+(v.currentTime-c.start)/c.speed;if(v.currentTime>=c.end-.03){nextClip();return}updateOverlay()});v.addEventListener('ended',()=>{if(playing)nextClip()});const music=asset(project.musicId);if(music){$('#music-preview').src=music.url;$('#music-preview').loop=true;$('#music-preview').volume=Math.min(1,project.musicVolume)}updateOverlay()}
function updateOverlay(){if(!$('#video'))return;syncAudio();const bg=$('#canvas-background'),fg=$('#video');if(bg&&project.canvasBackground==='blur'){if(Math.abs(bg.currentTime-fg.currentTime)>.2)bg.currentTime=fg.currentTime;if(playing&&bg.paused)bg.play().catch(()=>{});if(!playing&&!bg.paused)bg.pause()}styleCaptionOverlay();$('#caption-overlay').style.color=project.captionColor;$('#caption-overlay').style.fontSize=($('#stage').clientHeight*project.captionSize)+'px';$('#title-overlay').textContent=project.titles.filter(c=>playhead>=c.start&&playhead<c.end).map(c=>c.text).join('\n');$('#time').innerHTML=`${fmt(playhead)} <span class="muted">/ ${fmt(total())}</span>`;$('#scrubber').value=playhead;$('#play').textContent=playing?'Ⅱ':'▶'}
async function play(){if(!project.clips.length)return toast('Add a video to the timeline first.');if(!clip()){selected=project.clips[0].id;render()}if(playhead>=total()-.04){seekTo(0)}const v=$('#video');playing=true;try{await v.play();const music=asset(project.musicId);if(music){$('#music-preview').currentTime=playhead%music.duration;$('#music-preview').play().catch(()=>{})}}catch(e){playing=false;toast('This format cannot preview here. Export can still convert it: '+e.message,true)}updateOverlay()}
function pause(){playing=false;audioPlayers.forEach(p=>p.audio.pause());$('#video')?.pause();$('#music-preview')?.pause();$('#canvas-background')?.pause();updateOverlay()}
function nextClip(){const index=project.clips.findIndex(c=>c.id===selected);if(index+1>=project.clips.length){playhead=total();pause();return}selected=project.clips[index+1].id;playhead=offset(index+1);const resume=playing;pause();render();if(resume)play()}
function seekTo(time){const resume=playing;pause();playhead=Math.min(total(),Math.max(0,time));let sum=0;const c=project.clips.find((c,i)=>{const end=sum+duration(c);const found=playhead<end||i===project.clips.length-1;sum=end;return found});if(c&&c.id!==selected){selected=c.id;render()}else if(c){$('#video').currentTime=c.start+(playhead-offset(project.clips.indexOf(c)))*c.speed;updateOverlay()}if(resume)play()}
function bind(){
  $('#project-name').onchange=e=>change(()=>project.name=e.target.value||'Untitled story',{full:false});
  $('#quick-ratio').onchange=e=>change(()=>project.ratio=e.target.value);
  $('#scrubber').oninput=e=>seekTo(+e.target.value);
  $('#file-input').onchange=e=>importFiles(e.target.files);
  $('#subtitle-input').onchange=e=>readSubtitles(e.target.files[0]);
  $('#project-input').onchange=e=>loadProjectFile(e.target.files[0]);
  const drop=$('#dropzone');if(drop){drop.ondragover=e=>{e.preventDefault();drop.style.borderColor='#b9f675'};drop.ondragleave=()=>drop.style.borderColor='';drop.ondrop=e=>{e.preventDefault();importFiles(e.dataTransfer.files)}}
  $('#speech-engine')?.addEventListener('change',e=>localStorage.setItem('framecut-speech',e.target.value));
}
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.audio){const a=project.audioClips.find(c=>c.id===selectedAudio),key=t.dataset.audio,value=+t.value;if(a){const next={...a,[key]:value};if(!Number.isFinite(value)||next.start<0||next.end>asset(a.mediaId).duration||next.end-next.start<.05||next.position<0){toast('Choose a valid audio range.',true);render();return}change(()=>a[key]=value)}return}if(t.dataset.project){const key=t.dataset.project;change(()=>project[key]=t.type==='checkbox'?t.checked:t.type==='range'||t.type==='number'?+t.value:t.value)}if(t.dataset.clip&&clip()){const c=clip(),key=t.dataset.clip,value=+t.value,m=asset(c.mediaId);if(key==='start'&&(value<0||value>=c.end-.04)||key==='end'&&(value>m.duration||value<=c.start+.04))return render();change(()=>{c[key]=value;playhead=offset(project.clips.indexOf(c))})}for(const type of ['caption','title'])if(t.dataset[type]!==undefined){const list=type==='caption'?project.captions:project.titles,index=+t.dataset[type],key=t.dataset.key;const value=key==='text'?t.value:+t.value;if(key!=='text'&&(!Number.isFinite(value)||value<0))return render();const row={...list[index],[key]:value};if(row.end<=row.start){toast('End time must be after start time.',true);return render()}change(()=>{list[index]=row;if(key==='text')delete list[index].words},{full:false})}});
document.addEventListener('click',async e=>{
  const t=e.target.closest('button,[data-select],[data-seek]');if(!t)return;
  try {
    if(t.dataset.tab){tab=t.dataset.tab;if(tab!=='audio')selectedAudio=null;render();return}
    if(t.dataset.addAudio){addAudio(t.dataset.addAudio);return}
    if(t.dataset.selectAudio){selectedAudio=t.dataset.selectAudio;tab='audio';render();return}
    if(t.dataset.removeAudio){change(()=>{project.audioClips=project.audioClips.filter(c=>c.id!==t.dataset.removeAudio);if(selectedAudio===t.dataset.removeAudio)selectedAudio=null});return}
    if(t.dataset.add){const m=asset(t.dataset.add);if(!m)return;if(m.video)change(()=>{const c={id:uid(),mediaId:m.id,start:0,end:m.duration,speed:1,volume:1,fade:0,brightness:0,contrast:1,saturation:1};project.clips.push(c);selected=c.id;playhead=offset(project.clips.length-1)});else addAudio(m.id);return}
    if(t.dataset.select){pause();selectedAudio=null;selected=t.dataset.select;playhead=offset(project.clips.findIndex(c=>c.id===selected));render();return}
    if(t.dataset.seek){seekTo(+t.dataset.seek);return}
    if(t.dataset.ratio){change(()=>project.ratio=t.dataset.ratio);return}
    if(t.dataset.removeCaption!==undefined){change(()=>project.captions.splice(+t.dataset.removeCaption,1));return}
    if(t.dataset.removeTitle!==undefined){change(()=>project.titles.splice(+t.dataset.removeTitle,1));return}
    if(t.dataset.captionPreset){applyCaptionPreset(t.dataset.captionPreset);return}if(t.dataset.blurPreset){change(()=>{project.canvasBackground='blur';project.canvasBlur=+t.dataset.blurPreset;project.fit='contain'});return}const action=t.dataset.action;if(!action)return;
    if(action==='import')$('#file-input').click();
    if(action==='play')playing?pause():play();
    if(action==='previous')seekTo(offset(Math.max(0,project.clips.findIndex(c=>c.id===selected)-1)));
    if(action==='next')seekTo(offset(Math.min(project.clips.length-1,project.clips.findIndex(c=>c.id===selected)+1)));
    if(action==='split')selectedAudio?splitAudio():split();
    if(action==='detach-audio')detachAudio();
    if(action==='split-audio')splitAudio();
    if(action==='delete'&&selectedAudio){change(()=>{project.audioClips=project.audioClips.filter(c=>c.id!==selectedAudio);selectedAudio=null});return}
    if(action==='duplicate'&&selectedAudio){const a=project.audioClips.find(c=>c.id===selectedAudio);if(a)change(()=>project.audioClips.push({...a,id:uid(),position:a.position+duration(a)}));return}
    if(action==='delete'&&clip())change(()=>{project.clips=project.clips.filter(c=>c.id!==selected);selected=project.clips[0]?.id||null;playhead=0});
    if(action==='duplicate'&&clip())change(()=>project.clips.splice(project.clips.indexOf(clip())+1,0,{...clip(),id:uid()}));
    if(['move-left','move-right'].includes(action)&&clip())change(()=>{const i=project.clips.indexOf(clip()),j=i+(action==='move-left'?-1:1);if(j>=0&&j<project.clips.length)[project.clips[i],project.clips[j]]=[project.clips[j],project.clips[i]];playhead=offset(project.clips.findIndex(c=>c.id===selected))});
    if(action==='undo'&&undo.length){selectedAudio=null;redo.push(JSON.stringify(project));project=JSON.parse(undo.pop());selected=project.clips[0]?.id||null;playhead=0;save();render()}
    if(action==='redo'&&redo.length){selectedAudio=null;undo.push(JSON.stringify(project));project=JSON.parse(redo.pop());selected=project.clips[0]?.id||null;playhead=0;save();render()}
    if(action==='zoom-in'){zoom=Math.min(240,zoom*1.5);renderTimeline()}
    if(action==='zoom-out'){zoom=Math.max(5,zoom/1.5);renderTimeline()}
    if(action==='captions-tab'){tab='captions';render()}
    if(action==='add-caption')change(()=>{project.captions.push({start:+playhead.toFixed(2),end:+(Math.min(total()||playhead+3,playhead+3)).toFixed(2),text:'Your caption here'});tab='captions'});
    if(action==='add-title')change(()=>project.titles.push({start:+playhead.toFixed(2),end:+(playhead+3).toFixed(2),text:'Your title here'}));
    if(action==='import-subtitles')$('#subtitle-input').click();
    if(action==='save-subtitles')download(project.name+'.srt',project.captions.map((c,i)=>`${i+1}\n${clock(c.start)} --> ${clock(c.end)}\n${c.text}\n`).join('\n'));
    if(action==='settings')settings();
    if(action==='export')exportModal();
    if(action==='transcribe')await transcribe();
    if(action==='silence')await removeSilence();
    if(action==='ai-write')await writeAi();
    if(action==='copy-ai'){await navigator.clipboard.writeText(aiResult);toast('Copied to clipboard.')}
    if(action==='project-menu')projectMenu();
    if(action==='help')help();
  }catch(err){toast(err.message,true)}
});
function split(){const c=clip();if(!c)return;const source=c.start+(playhead-offset(project.clips.indexOf(c)))*c.speed;if(source-c.start<.05||c.end-source<.05)return toast('Move the playhead inside the selected clip before splitting.');change(()=>{const i=project.clips.indexOf(c),right={...c,id:uid(),start:source};c.end=source;project.clips.splice(i+1,0,right)})}
async function importFiles(files){if(!files?.length)return;toast('Importing media…');const form=new FormData();for(const f of files)form.append('files',f);try{const r=await fetch('/api/import',{method:'POST',body:form}),data=await r.json();if(!r.ok)throw Error(data.error);media.push(...data.assets);render();if(data.errors.length)toast(data.errors.map(e=>e.name+': '+e.error).join('\n'),true);else toast(`${data.assets.length} file${data.assets.length===1?'':'s'} added. Click + to add to your timeline.`)}catch(e){toast(e.message,true)}}
function modal(html,wide=false){pause();$('.modal-backdrop')?.remove();const el=document.createElement('div');el.className='modal-backdrop';el.innerHTML=`<div class="modal ${wide?'wide':''}" role="dialog" aria-modal="true">${html}</div>`;document.body.append(el);el.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>el.remove());return el}
function settings(){const el=modal(`<header><h1>AI connections</h1><button data-close>×</button></header><p class="muted">One connection. Easy switching. Your editor works with AI turned off.</p>${field('Provider preset',select([['ollama','Local · Ollama'],['lmstudio','Local · LM Studio'],['openai','OpenAI'],['groq','Groq'],['custom','Custom · OpenAI-compatible API']],ai.preset,'id="ai-preset"'))}<div class="notice">Local models run on your computer. For cloud providers, text or selected audio is sent only when you use an AI tool. API keys stay in memory for this app session.</div>${field('API base URL','<input id="ai-url" placeholder="https://your-provider.example/v1" value="'+esc(ai.baseUrl)+'">')}${field('API key (optional for local servers)','<input id="ai-key" type="password" autocomplete="off" placeholder="Paste your API key" value="'+esc(ai.key)+'">')}<div class="row" style="margin-bottom:20px"><button class="primary" id="verify-ai">Test connection & list models</button><span class="helper" id="verify-result">${ai.verified?'Connected':'Not tested this session'}</span></div><datalist id="ai-models">${ai.models.map(m=>`<option value="${esc(m)}">`).join('')}</datalist><div class="grid">${field('Text model','<input id="ai-model" list="ai-models" placeholder="Choose or enter a model ID" value="'+esc(ai.model)+'">')}${field('Speech model · API captions','<input id="ai-speech-model" list="ai-models" placeholder="whisper-1" value="'+esc(ai.speechModel)+'">')}</div><p class="helper">A connection check verifies the URL and credentials through /models. Text requires /chat/completions; API captions require /audio/transcriptions with timed verbose_json segments. APIs with different protocols need an adapter. Local Whisper captions use a separate built-in speech engine.</p><footer><button data-close>Cancel</button><button class="primary" id="save-ai">Use this connection</button></footer>`,true);
  const read=()=>({preset:$('#ai-preset').value,baseUrl:$('#ai-url').value,key:$('#ai-key').value,model:$('#ai-model').value,speechModel:$('#ai-speech-model').value,models:ai.models});
  $('#ai-preset').onchange=()=>{const p=$('#ai-preset').value;const urls={ollama:'http://127.0.0.1:11434/v1',lmstudio:'http://127.0.0.1:1234/v1',openai:'https://api.openai.com/v1',groq:'https://api.groq.com/openai/v1'};if(urls[p])$('#ai-url').value=urls[p];$('#ai-key').value='';$('#ai-model').value='';$('#ai-speech-model').value=p==='groq'?'whisper-large-v3':'whisper-1';$('#verify-result').textContent='Not tested';};
  $('#verify-ai').onclick=async()=>{const btn=$('#verify-ai');btn.disabled=true;$('#verify-result').textContent='Checking…';try{const data=await api('/api/ai/verify',read());ai={...read(),models:data.models,verified:true};$('#ai-models').innerHTML=data.models.map(m=>`<option value="${esc(m)}">`).join('');if(!$('#ai-model').value)$('#ai-model').value=data.models.find(m=>!m.includes('whisper')&&!m.includes('embed'))||'';$('#verify-result').textContent=`Connected · ${data.models.length} models`}catch(e){$('#verify-result').textContent=e.message;ai.verified=false}finally{btn.disabled=false}};
  $('#save-ai').onclick=async()=>{try{const next=read();await api('/api/ai/config',next);ai={...ai,...next};const {key,models,verified,...publicSettings}=ai;localStorage.setItem('framecut-ai',JSON.stringify(publicSettings));el.remove();toast('AI connection selected.')}catch(e){toast(e.message,true)}};
}
async function configAi(){await api('/api/ai/config',ai)}
async function transcribe(){const c=clip();if(!c)return toast('Select a video clip first.');if(!asset(c.mediaId)?.audio)return toast('The selected clip has no audio.',true);if(busy)return;const selectedId=c.id,snapshot={...c},start=offset(project.clips.indexOf(c));busy=true;transcribeStatus='Preparing selected audio…';render();try{let segments;
  if((localStorage.getItem('framecut-speech')||'local')==='api'){await configAi();const data=await api('/api/ai/transcribe',{mediaId:c.mediaId,start:c.start,end:c.end});segments=data.segments.map(s=>({start:s.start,end:s.end,text:s.text}))}
  else {const result=await api('/api/audio',{mediaId:c.mediaId,start:c.start,end:c.end});const bytes=await(await fetch(result.url)).arrayBuffer();const ctx=new AudioContext({sampleRate:16000});const buffer=await ctx.decodeAudioData(bytes);const audio=new Float32Array(buffer.getChannelData(0));await ctx.close();worker ||= new Worker(new URL('./transcribe.worker.js',import.meta.url),{type:'module'});segments=await new Promise((resolve,reject)=>{worker.onmessage=({data})=>{if(data.type==='progress'){transcribeStatus=data.message;const node=$('.busy');if(node)node.textContent=transcribeStatus}if(data.type==='error')reject(Error(data.message));if(data.type==='done')resolve((data.result.chunks||[]).map(x=>({start:x.timestamp[0]||0,end:x.timestamp[1]??result.duration,text:x.text})))};worker.onerror=e=>reject(Error(e.message||'Speech worker failed'));worker.postMessage({audio},[audio.buffer])})}
  const current=project.clips.find(c=>c.id===selectedId);if(!current||current.start!==snapshot.start||current.end!==snapshot.end||current.speed!==snapshot.speed)throw Error('The clip changed during transcription. Try again on the current edit.');
  checkpoint();project.captions=project.captions.filter(x=>x.end<=start||x.start>=start+duration(c));project.captions.push(...makeCaptionSegments(segments,start,c));project.captions.sort((a,b)=>a.start-b.start);save();toast(`${segments.length} caption segments generated.`);transcribeStatus='Captions ready to edit.';
  }catch(e){transcribeStatus='';toast(e.message,true)}finally{busy=false;render()}}
async function removeSilence(){const c=clip();if(!c)return toast('Select a clip first.');busy=true;render();try{const result=await api('/api/silence',{mediaId:c.mediaId});let cursor=c.start;const keep=[];for(const s of result.intervals){if(s.end<=c.start||s.start>=c.end)continue;const end=Math.max(c.start,s.start-.08);if(end-cursor>=.15)keep.push([cursor,end]);cursor=Math.min(c.end,s.end+.08)}if(c.end-cursor>=.15)keep.push([cursor,c.end]);if(!result.intervals.length||!keep.length)return toast('No useful pauses found to remove.');if(project.captions.length)return toast('Remove silence before adding captions so subtitle timing stays accurate.',true);change(()=>{const i=project.clips.indexOf(c);project.clips.splice(i,1,...keep.map(([start,end])=>({...c,id:uid(),start,end})));selected=project.clips[i].id;playhead=offset(i)});toast(`Kept ${keep.length} speaking sections. Ctrl+Z to undo.`)}catch(e){toast(e.message,true)}finally{busy=false;render()}}
async function writeAi(){if(!project.captions.length)return toast('Add or generate captions first.');const task=$('#ai-task').value,language=$('#ai-language').value;const tasks={titles:'Suggest five short, compelling video titles, one per line.',summary:'Summarize the following video transcript in a short paragraph.',description:'Write a concise video description based on this transcript.',translate:`Translate to ${language||'English'}. Keep the numbered lines and return only translated lines.`};busy=true;const text=project.captions.map((c,i)=>`${i+1}. ${c.text}`).join('\n');render();try{await configAi();const data=await api('/api/ai/text',{task:tasks[task],text});aiResult=data.text;toast('AI result is ready.')}catch(e){toast(e.message,true)}finally{busy=false;render()}}
function parseSubtitles(text){const lines=text.replace(/^\uFEFF/,'').replace(/\r/g,'').split('\n'),captions=[];const seconds=s=>{const a=s.replace(',','.').split(':').map(Number);return a.reduce((v,n)=>v*60+n,0)};for(let i=0;i<lines.length;i++){const m=lines[i].match(/(\d{1,2}:\d{2}(?::\d{2})?[.,]\d+)\s*-->\s*(\d{1,2}:\d{2}(?::\d{2})?[.,]\d+)/);if(!m)continue;const body=[];while(i+1<lines.length&&lines[i+1].trim())body.push(lines[++i]);const start=seconds(m[1]),end=seconds(m[2]);if(end>start)captions.push({start,end,text:body.join('\n').replace(/<[^>]+>/g,'')})}return captions}
async function readSubtitles(file){if(!file)return;const captions=parseSubtitles(await file.text());if(!captions.length)return toast('No timed captions were found in that file.',true);change(()=>{project.captions=captions;tab='captions'});toast(`${captions.length} captions imported.`)}
function exportModal(){if(!project.clips.length)return toast('Add a video to the timeline first.');const el=modal(`<header><h1>Ready for the world?</h1><button data-close>×</button></header><p class="muted">Export your story. All video processing happens on this computer.</p><div class="grid">${field('Format',select([['mp4','MP4 · most compatible'],['webm','WebM · web friendly'],['mp3','MP3 · audio mix'],['wav','WAV · lossless audio mix']],project.format,'id="export-format"'))}${field('Resolution',select([[480,'480p · draft'],[720,'720p · HD'],[1080,'1080p · Full HD'],[2160,'2160p · 4K']],project.resolution,'id="export-resolution"'))}${field('Frame rate',select([24,25,30,60].map(n=>[n,n+' fps']),project.fps,'id="export-fps"'))}${field('Quality',select([['balanced','Balanced'],['high','High quality'],['small','Smaller file']],project.quality,'id="export-quality"'))}</div><div class="notice">${project.ratio} ${ratios[project.ratio].toLowerCase()} · ${fmt(total())} · ${project.clips.length} clips${project.burnCaptions?` · ${project.captions.length} captions`:''}</div><div id="export-status"></div><footer><button data-close id="close-export">Cancel</button><button class="primary" id="start-export">Export video ↗</button></footer>`);
  $('#start-export').onclick=async()=>{try{project.format=$('#export-format').value;project.resolution=+$('#export-resolution').value;project.fps=+$('#export-fps').value;project.quality=$('#export-quality').value;save();const {id}=await api('/api/export',project);currentJob=id;$('#start-export').disabled=true;$('#close-export').textContent='Hide';$('#export-status').innerHTML='<p class="helper">Rendering your video… <span id="export-percent">0%</span></p><div class="progress"><div id="export-progress" style="width:0"></div></div><button id="cancel-job" class="danger">Stop export</button>';$('#cancel-job').onclick=async()=>{await api('/api/jobs/'+id,null,'DELETE');clearInterval(jobTimer);currentJob=null;el.remove();toast('Export cancelled.')};clearInterval(jobTimer);jobTimer=setInterval(async()=>{try{const j=await api('/api/jobs/'+id);const pct=Math.round(j.progress*100);if($('#export-progress'))$('#export-progress').style.width=pct+'%';if($('#export-percent'))$('#export-percent').textContent=pct+'%';if(j.status==='failed'){clearInterval(jobTimer);currentJob=null;toast('Export failed: '+j.error,true);if($('#export-status'))$('#export-status').innerHTML='<div class="notice error">'+esc(j.error)+'</div>';if($('#start-export'))$('#start-export').disabled=false}if(j.status==='done'){clearInterval(jobTimer);currentJob=null;toast('Your export is ready.');if($('.modal-backdrop')!==el)exportDone(id);else{el.remove();exportDone(id)}}}catch(e){clearInterval(jobTimer);toast(e.message,true)}},700)}catch(e){toast(e.message,true)}};
}
function exportDone(id){const el=modal('<header><h1>Your story is ready.</h1><button data-close>×</button></header><div class="notice">Export complete. Save the finished video wherever you like.</div><footer><button data-close>Close</button><button id="save-video" class="primary">Save video…</button></footer>');$('#save-video').onclick=async()=>{try{const data=await api('/api/jobs/'+id+'/save',{});if(data.download){const a=document.createElement('a');a.href='/api/jobs/'+id+'/download';a.download='';a.click()}if(data.saved||data.download){el.remove();toast('Video saved.')}}catch(e){toast(e.message,true)}}}
function projectMenu(){const el=modal(`<header><h1>Your project</h1><button data-close>×</button></header><p class="helper">Edits and imported media are saved locally. Project files contain edits and media IDs; they do not bundle source videos. Reopening on another computer requires relinking media.</p><div class="row"><button id="save-project">Save project file</button><button id="open-project">Open project file</button><button class="danger" id="new-project">New project</button></div>`);$('#save-project').onclick=()=>download(project.name+'.framecut',JSON.stringify({...project,mediaRefs:media.map(m=>({id:m.id,name:m.name,duration:m.duration}))},null,2),'application/json');$('#open-project').onclick=()=>{el.remove();$('#project-input').click()};$('#new-project').onclick=()=>{checkpoint();project=defaults();selectedAudio=null;selected=null;playhead=0;save();el.remove();render()}}
async function loadProjectFile(file){if(!file)return;try{const data=JSON.parse(await file.text());if(data.version!==1||!Array.isArray(data.clips)||data.clips.length>100)throw Error('Unsupported project file.');const refs=data.mediaRefs||[];for(const c of data.clips){if(!asset(c.mediaId)){const ref=refs.find(r=>r.id===c.mediaId);const found=media.find(m=>m.name===ref?.name&&Math.abs(m.duration-ref.duration)<.2);if(found)c.mediaId=found.id;else throw Error(`Import the missing media first: ${ref?.name||c.mediaId}`)}const m=asset(c.mediaId);if(!m.video||!Number.isFinite(c.start)||!Number.isFinite(c.end)||c.start<0||c.end>m.duration+.01||c.end<=c.start||!Number.isFinite(c.speed)||c.speed<.25||c.speed>4)throw Error('Project contains invalid clip settings.')}if(!Object.keys(ratios).includes(data.ratio))throw Error('Invalid aspect ratio.');change(()=>{project={...defaults(),...data,captions:validTimed(data.captions),titles:validTimed(data.titles)};selected=project.clips[0]?.id||null;playhead=0});toast('Project opened.')}catch(e){toast(e.message,true)}}
function validTimed(rows){return (Array.isArray(rows)?rows:[]).filter(c=>Number.isFinite(c.start)&&Number.isFinite(c.end)&&c.start>=0&&c.end>c.start&&typeof c.text==='string').slice(0,10000)}
function help(){modal(`<header><h1>A smaller editor. A simpler flow.</h1><button data-close>×</button></header><p>1. Import a video and click <b>+</b> to add it to the timeline.<br>2. Choose your aspect ratio. Use <b>Fit</b> for the whole frame or <b>Fill</b> to crop.<br>3. Select a clip to trim, change speed, adjust color, or set volume.<br>4. Add captions, text, and background music.<br>5. Click <b>Export video</b> and save your finished MP4 or WebM.</p><div class="notice">AI setup is optional. Built-in Whisper downloads its speech model on first use; after caching, it processes audio locally. For writing tools, run a text model in Ollama or LM Studio, or connect an API.</div><p class="helper">Space: play / pause · S: split · Delete: remove clip · Ctrl+Z: undo · Ctrl+Y: redo.<br>Preview is an editing guide. FFmpeg renders final captions, fades, color and audio. Higher-than-100% volume is applied at export; browser preview is limited to 100%. Clips join with straight cuts. Fade applies per clip; this version has no overlapping transitions or multitrack compositing.</p>`)}
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)||$('.modal-backdrop'))return;if(e.code==='Space'){e.preventDefault();playing?pause():play()}if(e.key.toLowerCase()==='s'&&!e.ctrlKey)selectedAudio?splitAudio():split();if(e.key==='Delete')document.querySelector('[data-action="delete"]')?.click();if(e.ctrlKey&&e.key.toLowerCase()==='z'){e.preventDefault();document.querySelector('[data-action="undo"]')?.click()}if(e.ctrlKey&&e.key.toLowerCase()==='y'){e.preventDefault();document.querySelector('[data-action="redo"]')?.click()}});
window.addEventListener('resize',updateOverlay);
async function boot(){try{api('/api/fonts').then(list=>{fonts=list;if(tab==='captions')render()}).catch(()=>{});media=await api('/api/media');const saved=await api('/api/project');if(saved?.version===1){project={...defaults(),...saved};selected=project.clips[0]?.id||null}render()}catch(e){$('#app').innerHTML='<p style="padding:40px">Could not start FrameCut: '+esc(e.message)+'</p>'}}
boot();

function addAudio(mediaId){const m=asset(mediaId);if(!m?.audio)return toast('This file has no audio.',true);change(()=>{const c={id:uid(),mediaId,start:0,end:m.duration,speed:1,position:Math.max(0,Math.min(playhead,total())),volume:.7,fadeIn:0,fadeOut:0};project.audioClips||=[];project.audioClips.push(c);selectedAudio=c.id;tab='audio'})}
function detachAudio(){const c=clip(),m=c&&asset(c.mediaId);if(!m?.audio)return toast('Select a video with audio.',true);change(()=>{const a={id:uid(),mediaId:c.mediaId,start:c.start,end:c.end,speed:c.speed,position:offset(project.clips.indexOf(c)),volume:c.volume,fadeIn:0,fadeOut:0};project.audioClips||=[];project.audioClips.push(a);c.volume=0;selectedAudio=a.id;tab='audio'});toast('Audio detached. The original clip is muted; your source file is intact.')}
function splitAudio(){const a=project.audioClips.find(c=>c.id===selectedAudio);if(!a)return toast('Select an audio clip first.');const source=a.start+(playhead-a.position)*a.speed;if(source-a.start<.05||a.end-source<.05)return toast('Move the playhead inside the audio clip first.');change(()=>{const right={...a,id:uid(),start:source,position:playhead};a.end=source;project.audioClips.push(right)});toast('Audio split into two independent clips.')}
function audioLibrary(){return '<div class="section-head"><h2>Audio & mix</h2><button data-action="import">+ Import</button></div><div class="panel-card"><h3>Your sound, your way</h3><p>Trim, chop and layer audio independently. Add music, voiceovers, or detach sound from a video.</p><button class="primary" data-action="detach-audio">Detach selected video audio</button></div>'+media.filter(m=>m.audio).map(m=>'<div class="asset"><div class="thumb">♫</div><div><div class="asset-name" title="'+esc(m.name)+'">'+esc(m.name)+'</div><small>'+fmt(m.duration)+(m.video?' · Video audio':' · Audio file')+'</small></div><button data-add-audio="'+m.id+'" title="Add audio track">+</button></div>').join('')+'<div class="divider"></div><h3>Mixing tracks · '+(project.audioClips||[]).length+'</h3>'+(project.audioClips||[]).map((c,i)=>'<div class="audio-card '+(selectedAudio===c.id?'selected':'')+'"><button class="audio-select" data-select-audio="'+c.id+'">♫ '+esc(asset(c.mediaId)?.name)+'<small>'+fmt(c.position)+' → '+fmt(c.position+duration(c))+' · '+Math.round(c.volume*100)+'%</small></button><button class="quiet danger" data-remove-audio="'+c.id+'" title="Remove audio">×</button></div>').join('')+'<div class="divider"></div>'+field('Looping background music',select([['','No looping music'],...media.filter(m=>m.audio&&!m.video).map(m=>[m.id,m.name])],project.musicId||'','data-project="musicId"'))+field('Background music level',pInput('musicVolume','range','min="0" max="2" step=".05"'))+'<p class="helper">Select a blue audio clip to open its controls. Audio beyond the end of your video is excluded from export.</p>'}
function audioInspector(){const c=project.audioClips.find(c=>c.id===selectedAudio);if(!c)return '<p class="helper">Select an audio track.</p>';const input=(key,attrs='')=>'<input type="number" data-audio="'+key+'" value="'+c[key]+'" '+attrs+'>';return '<div class="eyebrow">Sound workspace</div><h2>Audio clip</h2><div class="audio-badge">♫</div><h3>'+esc(asset(c.mediaId)?.name)+'</h3><p class="helper">Independent sound layer · '+fmt(duration(c))+'</p>'+field('Position on timeline (seconds)',input('position','min="0" step=".1"'))+'<div class="row">'+field('Source trim in',input('start','min="0" step=".1"'))+field('Source trim out',input('end','min=".05" step=".1"'))+'</div>'+field('Playback speed',select([.25,.5,.75,1,1.25,1.5,2,3,4].map(n=>[n,n+'×']),c.speed,'data-audio="speed"'))+field('Volume · '+Math.round(c.volume*100)+'%','<input type="range" data-audio="volume" min="0" max="2" step=".05" value="'+c.volume+'">')+'<div class="row">'+field('Fade in (seconds)',input('fadeIn','min="0" max="5" step=".1"'))+field('Fade out (seconds)',input('fadeOut','min="0" max="5" step=".1"'))+'</div>'+'<button class="full-width primary" data-action="split-audio">✂ Split audio at playhead</button><p class="helper" style="margin-top:14px">Drag the preview scrubber to your cut point, then split. Each piece gets its own trim, position, and volume controls. Use Remove to delete a piece.</p><div class="divider"></div><button class="full-width danger" data-remove-audio="'+c.id+'">Remove this audio clip</button>'}
function audioTracks(width){return (project.audioClips||[]).map((c,i)=>'<div class="audio-track" style="width:'+width+'px"><div class="track-label">AUDIO '+(i+1)+'</div><button class="audio-timeline-clip '+(selectedAudio===c.id?'selected':'')+'" data-select-audio="'+c.id+'" style="left:'+(c.position/Math.max(total(),.1)*width)+'px;width:'+Math.max(35,duration(c)/Math.max(total(),.1)*width)+'px">♫ '+esc(asset(c.mediaId)?.name)+' · '+Math.round(c.volume*100)+'%</button></div>').join('')}
function syncAudio(){for(const p of audioPlayers){const c=(project.audioClips||[]).find(c=>c.id===p.id);if(!c)continue;const active=playing&&playhead>=c.position&&playhead<c.position+duration(c);if(!active){if(!p.audio.paused)p.audio.pause();continue}const local=playhead-c.position,remaining=duration(c)-local;const fadeIn=c.fadeIn||0,fadeOut=c.fadeOut||0;const fade=Math.max(0,Math.min(1,fadeIn?local/fadeIn:1,fadeOut?remaining/fadeOut:1));p.audio.volume=Math.min(1,c.volume*fade);p.audio.playbackRate=c.speed;const desired=c.start+local*c.speed;if(Math.abs(p.audio.currentTime-desired)>.25)p.audio.currentTime=desired;if(p.audio.paused)p.audio.play().catch(()=>{})}}

function canvasControls(){return '<div class="canvas-controls">'+field('Canvas background',select([['blur','Blurred video · fills empty space'],['black','Black'],['color','Solid color']],project.canvasBackground,'data-project="canvasBackground"'))+(project.canvasBackground==='blur'?'<label>Blur strength</label><div class="blur-presets">'+[[6,'Light'],[14,'Soft'],[28,'Medium'],[44,'Strong']].map(([n,label])=>'<button data-blur-preset="'+n+'" class="'+(Math.abs(project.canvasBlur-n)<4?'selected':'')+'"><span style="filter:blur('+n/12+'px)">▰</span>'+label+'</button>').join('')+'</div>'+pInput('canvasBlur','range','min="3" max="60" step="1"')+'<p class="helper">Keeps the original frame intact over a blurred, full-size background. Choose Fit to see the canvas.</p>':project.canvasBackground==='color'?pInput('canvasColor','color'):'')+'</div>'}
function captionStylePanel(){return '<details class="caption-styles" open><summary>Make captions your own</summary><div class="caption-presets">'+[['clean','Clean'],['bold','Bold'],['boxed','Boxed'],['highlight','Word glow'],['minimal','Minimal'],['cinema','Cinema']].map(([id,label])=>'<button data-caption-preset="'+id+'" class="'+(project.captionPreset===id?'selected':'')+'">'+label+'</button>').join('')+'</div>'+field('Font family','<input list="caption-fonts" data-project="captionFont" value="'+esc(project.captionFont)+'" aria-label="Caption font"><datalist id="caption-fonts">'+fonts.map(f=>'<option value="'+esc(f)+'">').join('')+'</datalist>')+'<div class="row">'+field('Text color',pInput('captionColor','color'))+field('Position',select([['bottom','Bottom'],['middle','Center'],['top','Top']],project.captionPosition,'data-project="captionPosition"'))+'</div>'+field('Text size',pInput('captionSize','range','min=".025" max=".1" step=".002"'))+'<div class="row"><label><input type="checkbox" data-project="captionBold" '+(project.captionBold?'checked':'')+'> Bold</label><label><input type="checkbox" data-project="captionItalic" '+(project.captionItalic?'checked':'')+'> Italic</label><label><input type="checkbox" data-project="captionUppercase" '+(project.captionUppercase?'checked':'')+'> CAPS</label></div><div class="row"><label><input type="checkbox" data-project="captionBox" '+(project.captionBox?'checked':'')+'> Backdrop</label><label><input type="checkbox" data-project="captionShadow" '+(project.captionShadow?'checked':'')+'> Shadow</label></div>'+field('Outline thickness',pInput('captionOutline','range','min="0" max="10" step=".5"'))+'</details>'}
function applyCaptionPreset(name){const styles={clean:{captionFont:'Arial',captionBold:true,captionOutline:3,captionColor:'#ffffff',captionBox:false,captionItalic:false,captionUppercase:false},bold:{captionFont:'Impact',captionBold:true,captionOutline:5,captionColor:'#fff175',captionBox:false,captionUppercase:true},boxed:{captionFont:'Segoe UI',captionBold:true,captionOutline:0,captionColor:'#ffffff',captionBox:true,captionUppercase:false},highlight:{captionFont:'Arial',captionBold:true,captionOutline:4,captionColor:'#b9f675',captionBox:false,captionUppercase:false},minimal:{captionFont:'Segoe UI',captionBold:false,captionOutline:1,captionColor:'#ffffff',captionBox:false,captionUppercase:false},cinema:{captionFont:'Georgia',captionBold:false,captionOutline:2,captionColor:'#f5e6c4',captionBox:false,captionItalic:true,captionUppercase:false}};change(()=>Object.assign(project,{captionItalic:false},styles[name],{captionPreset:name}));if(name==='highlight'&&!project.captions.some(c=>c.words?.length))toast('Generate local auto-captions for timed word highlighting. Imported captions use the same style without word animation.')}
function styleCaptionOverlay(){const el=$('#caption-overlay'),height=$('#stage').clientHeight;const current=project.captions.filter(c=>playhead>=c.start&&playhead<c.end);el.innerHTML=current.map(c=>project.captionPreset==='highlight'&&c.words?.length?c.words.map(w=>'<span style="color:'+(playhead>=w.start?esc(project.captionColor):'#ffffff')+'">'+esc(project.captionUppercase?w.text.toUpperCase():w.text)+'</span>').join(' '):esc(project.captionUppercase?c.text.toUpperCase():c.text)).join('<br>');el.style.fontFamily=project.captionFont;el.style.fontWeight=project.captionBold?'750':'400';el.style.fontStyle=project.captionItalic?'italic':'normal';el.style.top=project.captionPosition==='top'?'8%':project.captionPosition==='middle'?'50%':'auto';el.style.bottom=project.captionPosition==='bottom'?'8%':'auto';el.style.transform=project.captionPosition==='middle'?'translateY(-50%)':'none';const stroke=project.captionOutline*height/1080;el.style.webkitTextStroke=stroke+'px #101010';el.style.paintOrder='stroke fill';el.style.textShadow=project.captionShadow?'0 2px 4px #000':'none';el.style.background=project.captionBox?'#000a':'none';el.style.borderRadius='5px';el.style.padding=project.captionBox?'6px 10px':'0';el.style.width='fit-content';el.style.maxWidth='88%';el.style.left='50%';el.style.right='auto';el.style.transform=(project.captionPosition==='middle'?'translate(-50%,-50%)':'translateX(-50%)');}
function makeCaptionSegments(segments,offset,c){const words=segments.map(s=>({start:offset+s.start/c.speed,end:offset+Math.min(s.end,c.end-c.start)/c.speed,text:s.text.trim()})).filter(w=>w.end>w.start&&w.text);if((localStorage.getItem('framecut-speech')||'local')==='api')return words;const result=[];let group=[];for(const w of words){group.push(w);if(group.length>=6||w.end-group[0].start>2.5||/[.!?]$/.test(w.text)){result.push({start:group[0].start,end:group.at(-1).end,text:group.map(w=>w.text).join(' '),words:group});group=[]}}if(group.length)result.push({start:group[0].start,end:group.at(-1).end,text:group.map(w=>w.text).join(' '),words:group});return result}
